import type {
  SelectTriggerProps,
  SelectValueProps,
  SelectIconProps,
  SelectContentProps,
  SelectItemProps,
  SelectGroupProps,
  SelectLabelProps,
  SelectProps,
  SelectItemLabelProps,
  SelectItemSubtextProps,
  SelectItemLeadingIconProps,
  SelectItemTrailingIconProps,
} from "./select.types";

import React, { forwardRef, useState, useEffect } from "react";
import * as RadixSelect from "@radix-ui/react-select";
import { Check as CheckIcon, ChevronDown } from "@exp-textura/icons";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { SelectClasses, StyledSelect } from "./select.styles";
import { SelectContext, useSelectContext, SelectContextValue } from "./hooks/use-select";

const SelectRoot = forwardRef<HTMLDivElement, SelectProps>(
  (
    {
      children,
      value: controlledValue,
      defaultValue,
      onValueChange: userOnValueChange,
      open: controlledOpen,
      defaultOpen = false,
      onOpenChange: userOnOpenChange,
      disabled = false,
      variant,
      styleSlots,
      placeholder,
      placeholderIcon,
      startAdornment,
      position = "popper",
      className,
      align,
      side,
      sideOffset = 4,
      alignOffset,
      arrowPadding,
      collisionPadding = 10,
      showSelectedIndicator = true,
      inputSize = "default",
      id,
      required,
      "aria-describedby": ariaDescribedBy,
      "aria-invalid": ariaInvalid,
      "aria-required": ariaRequired,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const [hasSelection, setHasSelection] = useState(Boolean(controlledValue || defaultValue));
    const [isInternalOpen, setInternalOpen] = useState(defaultOpen);

    const open = controlledOpen ?? isInternalOpen;

    const onOpenChange = (newOpen: boolean) => {
      setInternalOpen(newOpen);
      userOnOpenChange?.(newOpen);
    };

    const resolvedPlaceholder = (
      <span className={SelectClasses.placeholderWrapper}>
        {placeholderIcon}
        {placeholder}
      </span>
    );

    useEffect(() => {
      if (controlledValue !== undefined) {
        setHasSelection(Boolean(controlledValue));
      }
    }, [controlledValue]);

    useEffect(() => {
      if (controlledValue === undefined && defaultValue !== undefined) {
        setHasSelection(Boolean(defaultValue));
      }
    }, [controlledValue, defaultValue]);

    const handleRadixValueChange = (newValue: string) => {
      setHasSelection(Boolean(newValue));
      userOnValueChange?.(newValue);
    };

    const radixRootProps = {
      value: controlledValue,
      defaultValue,
      onValueChange: handleRadixValueChange,
      open,
      onOpenChange,
      disabled,
      required,
    };

    const contextValue: SelectContextValue = {
      theme,
      variant,
      styleSlots,
      placeholder: resolvedPlaceholder,
      startAdornment,
      hasSelection,
      position,
      align,
      side,
      sideOffset,
      alignOffset,
      arrowPadding,
      collisionPadding,
      value: controlledValue,
      defaultValue,
      onValueChange: userOnValueChange,
      open,
      defaultOpen,
      onOpenChange,
      disabled,
      showSelectedIndicator,
      inputSize,
      id,
      "aria-describedby": ariaDescribedBy,
      "aria-invalid": ariaInvalid,
      "aria-required": ariaRequired,
      required,
    };

    return (
      <SelectContext.Provider value={contextValue}>
        <StyledSelect
          ref={ref}
          className={clsx(SelectClasses.root, className, {
            [SelectClasses.sm]: inputSize === "sm",
            [SelectClasses.hasSelection]: hasSelection,
          })}
          currentTheme={theme}
          styleSlots={styleSlots}
          variant={variant}
          {...props}
        >
          <RadixSelect.Root {...radixRootProps}>{children}</RadixSelect.Root>
        </StyledSelect>
      </SelectContext.Provider>
    );
  },
);
SelectRoot.displayName = "Select";

const Trigger = forwardRef<HTMLButtonElement, SelectTriggerProps>(
  ({ className, children, ...props }, ref) => {
    const {
      id,
      "aria-describedby": ariaDescribedBy,
      "aria-invalid": ariaInvalid,
      "aria-required": required,
      open,
      onOpenChange,
      startAdornment,
    } = useSelectContext();

    const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
      if (event.key.length === 1 && !event.ctrlKey && !event.metaKey && !open) {
        onOpenChange?.(true);
      }
    };

    return (
      <RadixSelect.Trigger
        ref={ref}
        aria-describedby={ariaDescribedBy}
        aria-invalid={ariaInvalid}
        aria-required={required}
        className={clsx(SelectClasses.trigger, className)}
        id={id}
        onKeyDown={handleKeyDown}
        {...props}
      >
        {startAdornment && <span className={SelectClasses.startAdornment}>{startAdornment}</span>}
        {children}
      </RadixSelect.Trigger>
    );
  },
);
Trigger.displayName = "Select.Trigger";

const Value: React.FC<SelectValueProps> = ({ className, children, ...props }) => {
  const { placeholder } = useSelectContext();
  return (
    <RadixSelect.Value
      className={clsx(SelectClasses.value, className)}
      placeholder={placeholder}
      {...props}
    >
      {children}
    </RadixSelect.Value>
  );
};
Value.displayName = "Select.Value";

const Icon = forwardRef<HTMLSpanElement, SelectIconProps>(
  ({ className, children = <ChevronDown />, ...props }, ref) => {
    return (
      <RadixSelect.Icon
        ref={ref}
        className={clsx(SelectClasses.triggerIcon, className)}
        {...props}
        asChild
      >
        {children}
      </RadixSelect.Icon>
    );
  },
);
Icon.displayName = "Select.Icon";

const Content = forwardRef<HTMLDivElement, SelectContentProps>(
  ({ className, children, ...props }, ref) => {
    const {
      theme,
      variant,
      styleSlots,
      align,
      position,
      side,
      sideOffset,
      alignOffset,
      arrowPadding,
      collisionPadding,
    } = useSelectContext();

    const radixContentProps = {
      align,
      position,
      side,
      sideOffset,
      alignOffset,
      arrowPadding,
      collisionPadding,
      ...props,
    };

    return (
      <RadixSelect.Portal>
        <StyledSelect
          currentTheme={theme}
          data-radix-popper-wrapper="true"
          styleSlots={styleSlots}
          variant={variant}
        >
          <RadixSelect.Content
            ref={ref}
            className={clsx(SelectClasses.content, className)}
            {...radixContentProps}
          >
            <RadixSelect.Viewport className={SelectClasses.viewport}>
              {children}
            </RadixSelect.Viewport>
          </RadixSelect.Content>
        </StyledSelect>
      </RadixSelect.Portal>
    );
  },
);
Content.displayName = "Select.Content";

const SelectItemLabel = forwardRef<HTMLSpanElement, SelectItemLabelProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(SelectClasses.label, className)} {...props}>
      {children}
    </span>
  ),
);
SelectItemLabel.displayName = "Select.ItemLabel";

const SelectItemSubtext = forwardRef<HTMLSpanElement, SelectItemSubtextProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(SelectClasses.subtext, className)} {...props}>
      {children}
    </span>
  ),
);
SelectItemSubtext.displayName = "Select.ItemSubtext";

const SelectItemLeadingIcon = forwardRef<HTMLSpanElement, SelectItemLeadingIconProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(SelectClasses.leadingIcon, className)} {...props}>
      {children}
    </span>
  ),
);
SelectItemLeadingIcon.displayName = "Select.ItemLeadingIcon";

const SelectItemTrailingIcon = forwardRef<HTMLSpanElement, SelectItemTrailingIconProps>(
  ({ children, className, ...props }, ref) => (
    <span ref={ref} className={clsx(SelectClasses.trailingIcon, className)} {...props}>
      {children}
    </span>
  ),
);
SelectItemTrailingIcon.displayName = "Select.ItemTrailingIcon";

const Item = forwardRef<HTMLDivElement, SelectItemProps>(
  ({ className, children, value, disabled, ...props }, ref) => {
    const { hasSelection, showSelectedIndicator, inputSize } = useSelectContext();

    // Automatically wrap string children with SelectItemLabel for convenience
    const content = React.Children.map(children, (child) =>
      typeof child === "string" ? <SelectItemLabel>{child}</SelectItemLabel> : child,
    );

    const leadingIcon = React.Children.toArray(content).find(
      (child) =>
        React.isValidElement(child) &&
        (child.type as { displayName?: string }).displayName === SelectItemLeadingIcon.displayName,
    );

    const trailingIcon = React.Children.toArray(content).find(
      (child) =>
        React.isValidElement(child) &&
        (child.type as { displayName?: string }).displayName === SelectItemTrailingIcon.displayName,
    );

    const subtext = React.Children.toArray(content).find(
      (child) =>
        React.isValidElement(child) &&
        (child.type as { displayName?: string }).displayName === SelectItemSubtext.displayName,
    );

    const labelContent = React.Children.toArray(content).filter(
      (child) =>
        React.isValidElement(child) &&
        (child.type as { displayName?: string }).displayName !==
          SelectItemLeadingIcon.displayName &&
        (child.type as { displayName?: string }).displayName !==
          SelectItemTrailingIcon.displayName &&
        (child.type as { displayName?: string }).displayName !== SelectItemSubtext.displayName,
    );

    const hasSubtext = Boolean(subtext);

    return (
      <RadixSelect.Item
        ref={ref}
        className={clsx(
          SelectClasses.item,
          {
            [SelectClasses.hasSelectedItemPadding]: hasSelection && showSelectedIndicator,
            [SelectClasses.itemSm]: inputSize === "sm",
          },
          className,
        )}
        data-has-subtext={hasSubtext ? true : undefined}
        disabled={disabled}
        value={value}
        {...props}
      >
        {showSelectedIndicator && (
          <RadixSelect.ItemIndicator className={SelectClasses.itemIndicator}>
            <CheckIcon />
          </RadixSelect.ItemIndicator>
        )}

        <div className={SelectClasses.textWrapper}>
          <RadixSelect.ItemText asChild>
            <span className={SelectClasses.itemText}>
              {leadingIcon}
              {labelContent.length === 1 &&
              React.isValidElement(labelContent[0]) &&
              (labelContent[0].type as { displayName?: string }).displayName ===
                SelectItemLabel.displayName ? (
                labelContent[0]
              ) : (
                <span className={SelectClasses.label}>{labelContent}</span>
              )}
            </span>
          </RadixSelect.ItemText>
          {subtext}
        </div>

        {trailingIcon}
      </RadixSelect.Item>
    );
  },
);
Item.displayName = "Select.Item";

const Group: React.FC<SelectGroupProps> = ({ className, children, ...props }) => {
  return (
    <RadixSelect.Group className={className} {...props}>
      {children}
    </RadixSelect.Group>
  );
};
Group.displayName = "Select.Group";

const Label = forwardRef<HTMLDivElement, SelectLabelProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <RadixSelect.Label ref={ref} className={clsx(SelectClasses.groupLabel, className)} {...props}>
        {children}
      </RadixSelect.Label>
    );
  },
);
Label.displayName = "Select.Label";

const Divider = forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof RadixSelect.Separator>
>(({ children, className, ...props }, ref) => (
  <RadixSelect.Separator ref={ref} className={clsx(SelectClasses.divider, className)} {...props}>
    {children}
  </RadixSelect.Separator>
));
Divider.displayName = "Select.Divider";

const Select = Object.assign(SelectRoot, {
  Trigger,
  Value,
  Icon,
  Content,
  Item,
  Group,
  Label,
  Divider,
  ItemLabel: SelectItemLabel,
  ItemSubtext: SelectItemSubtext,
  ItemLeadingIcon: SelectItemLeadingIcon,
  ItemTrailingIcon: SelectItemTrailingIcon,
});

export default Select;
